sys_variable_value.value:
(function execute(inputs, outputs) {
  var r = JSON.parse(inputs.body).result;
  outputs.summary = 'probe=' + r.probe + ' header=' + r.header + ' / HTTP ' + inputs.code;
})(inputs, outputs);

